<script lang="ts">
  import { onMount } from 'svelte';
  import { Dialogs } from '@wailsio/runtime';
  import { Analyze, DefaultConfig, SaveJSON } from '../bindings/go-spectrogram-plotly/desktop/analysisservice';
  import type { Config, Result } from '../bindings/go-spectrogram-plotly/internal/spectrogram/models';

  let config: Config = $state({ FFTSize: 1024, HopSize: 512, Channel: 'mono', MinDB: -100, MaxDB: 0, MaxFrames: 2000 });
  let path = $state(''); let result: Result | null = $state(null); let error = $state(''); let busy = $state(false); let canvas: HTMLCanvasElement | undefined = $state();
  onMount(async () => { config = await DefaultConfig(); config.MaxFrames = 2000; });
  async function analyze() { if (!path.trim()) { error = 'Enter a WAV or MP3 path.'; return; }; busy = true; error = ''; result = null; try { result = await Analyze(path.trim(), config); requestAnimationFrame(draw); } catch (e) { error = e instanceof Error ? e.message : String(e); } finally { busy = false; } }
  async function chooseFile() { const selected = await Dialogs.OpenFile({ Title: 'Choose audio', CanChooseFiles: true, AllowsMultipleSelection: false, Filters: [{ DisplayName: 'Audio', Pattern: '*.wav;*.mp3' }] }); if (selected) path = selected as string; }
  async function saveJSON() { if (!result) return; const target = await Dialogs.SaveFile({ Title: 'Export spectrogram JSON', Filename: 'spectrogram.json', Filters: [{ DisplayName: 'JSON', Pattern: '*.json' }] }); if (target) await SaveJSON(target, result); }
  function draw() { if (!result?.data?.length || !canvas) return; const rows = result.data as number[][], bins = rows[0].length, w = Math.min(1200, Math.max(400, rows.length)), h = Math.min(700, Math.max(240, bins)), ctx = canvas.getContext('2d'); if (!ctx) return; canvas.width=w; canvas.height=h; const img=ctx.createImageData(w,h); for(let x=0;x<w;x++)for(let y=0;y<h;y++){const v=rows[Math.floor(x*rows.length/w)][Math.floor((h-1-y)*bins/h)], t=Math.max(0,Math.min(1,(v-result.metadata.minDb)/(result.metadata.maxDb-result.metadata.minDb))), p=(y*w+x)*4; img.data[p]=68+185*t; img.data[p+1]=1+230*t; img.data[p+2]=84-47*t; img.data[p+3]=255}; ctx.putImageData(img,0,0); }
</script>

<main><header><div><small>LOCAL AUDIO ANALYSIS</small><h1>Spectogram</h1></div><span>{busy ? 'Analyzing…' : 'Ready'}</span></header><div class="workspace"><aside><h2>Open audio</h2><label>Audio file<input bind:value={path} placeholder="/Users/you/Music/track.wav" onkeydown={(e)=>e.key==='Enter'&&analyze()} /></label><button class="secondary" onclick={chooseFile}>Choose audio file</button><p>WAV and MP3 are processed locally.</p><h2>Analysis</h2><label>FFT<select bind:value={config.FFTSize}><option value={512}>512</option><option value={1024}>1024</option><option value={2048}>2048</option></select></label><label>Hop<select bind:value={config.HopSize}><option value={256}>256</option><option value={512}>512</option></select></label><label>Channel<select bind:value={config.Channel}><option value="mono">Mono</option><option value="left">Left</option><option value="right">Right</option><option value="side">Side</option></select></label><label>Max frames<input type="number" min="0" bind:value={config.MaxFrames}/></label><button onclick={analyze} disabled={busy}>{busy?'Analyzing…':'Analyze audio'}</button>{#if error}<strong>{error}</strong>{/if}</aside><section class="viewer">{#if result}<div class="meta">{result.metadata.sampleRate} Hz · {result.metadata.durationSeconds.toFixed(2)} seconds · FFT {result.metadata.fftSize} · {result.data?.length ?? 0} frames <button class="export" onclick={saveJSON}>Export JSON</button></div><canvas bind:this={canvas}></canvas>{:else}<div class="empty"><b>∿</b><h2>Choose an audio file</h2><p>Configure the analysis, then generate a local spectrogram.</p></div>{/if}</section></div></main>

<style>
  :global(*){box-sizing:border-box}:global(body){margin:0;background:#0b1020;color:#e7edf7;font-family:system-ui,sans-serif}main{min-height:100vh;background:radial-gradient(circle at 80% 0,#1d2857,transparent 34%),#0b1020}header{height:88px;padding:18px 32px;display:flex;justify-content:space-between;align-items:center;border-bottom:1px solid #283252}small{color:#8ba6ff;font-weight:700;letter-spacing:1.4px}h1,h2,p{margin:0}h1{font-size:25px}.workspace{display:grid;grid-template-columns:310px 1fr;min-height:calc(100vh - 88px)}aside{padding:28px;background:#0e1427;border-right:1px solid #283252}h2{font-size:15px;margin:0 0 14px}label{display:block;color:#aeb9d2;font-size:12px;margin:14px 0}input,select{width:100%;margin-top:6px;padding:10px;color:#e7edf7;background:#141d36;border:1px solid #344266;border-radius:6px}button{width:100%;margin-top:14px;padding:12px;border:0;border-radius:6px;background:#7795ff;color:#08102b;font-weight:750}.secondary{margin-top:0;background:#1a2748;color:#b9c9ff;border:1px solid #465987}.export{width:auto;margin:0 0 0 12px;padding:6px 9px;font-size:12px}p,strong{display:block;margin-top:10px;color:#8290b2;font-size:12px;line-height:1.45}strong{color:#ff9da5}.viewer{padding:32px;overflow:auto}.meta{margin-bottom:16px;color:#bdc9e6;font-size:12px}canvas{width:100%;max-height:72vh;object-fit:fill;border:1px solid #344266;background:#060a16}.empty{height:calc(100vh - 190px);display:grid;place-content:center;text-align:center;color:#9ba8c7}.empty b{font-size:72px;color:#7795ff}@media(max-width:780px){.workspace{grid-template-columns:1fr}aside{border-right:0;border-bottom:1px solid #283252}}
</style>
